+import { createEventCard } from "./event-card.js";
+import { buildRoster } from "./roster.js";
+import { csvCell } from "../lib/text.js";
+
+const toCsvLine = (cells) => cells.map(csvCell).join(",") + "\n";
+
+export function exportRosterCsv(event, signups) {
+  const card = createEventCard(event);
+  const rows = buildRoster(signups).map((entry) =>
+    toCsvLine([card.title, card.dateLabel, entry.name, entry.email]));
+  return toCsvLine(["event", "date", "name", "email"]) + rows.join("");
+}

