@@ -0,0 +1,15 @@
+import { sortByStartsAt } from "./agenda.js";
+import { summarizeAttendance } from "./attendance.js";
+import { createEventCard } from "./event-card.js";
+
+function signupsFor(signupsByEvent, id) {
+  return signupsByEvent != null && Object.hasOwn(signupsByEvent, id) ? signupsByEvent[id] : [];
+}
+
+export function buildOrganizerDigest(events, signupsByEvent) {
+  const entries = new Map(events.map((event) => {
+    const card = createEventCard(event);
+    return [event, { ...card, ...summarizeAttendance(event, signupsFor(signupsByEvent, card.id)) }];
+  }));
+  return sortByStartsAt(events).map((event) => entries.get(event));
+}

